template.script:
(function () {
  document.querySelectorAll('a[data-enviado-url]').forEach(function (link) {
    link.addEventListener('click', function () {
      var url = link.getAttribute('data-enviado-url');
      try {
        fetch(url, {method: 'POST', keepalive: true, credentials: 'same-origin'});
      } catch (e) {
        if (navigator.sendBeacon) { navigator.sendBeacon(url); }
      }
      var paso = link.closest('#paso-empresa');
      if (paso) { paso.setAttribute('data-enviado', '1'); }
    });
  });
})();
